/**
 * Amount carried in a `PolicyIntent`. The wire layer (REST / MCP)
 * passes user-friendly decimal strings (`"0.1"` ETH); the policy
 * engine resolves these to base units against the token's `decimals()`
 * view. Some legacy call sites already have a `U256` in base units;
 * those use [`IntentAmount::BaseUnits`] to skip the resolver.
 */

public enum IntentAmount {
    
    /**
     * User-facing decimal string in token units (e.g. `"0.1"`).
     */
    case decimal(String
    )
    /**
     * Already in the token's smallest unit. No resolver lookup needed.
     */
    case baseUnits(U256
    )
}


