        switch variant {
        
        case 1: return .decimal(try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .baseUnits(try FfiConverterTypeU256.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: IntentAmount, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .decimal(v1):
